pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 nCalls, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 0, 10 ether);
        nCalls = bound(nCalls, 1, 5);

        vm.deal(actor, amount * nCalls);
        for (uint256 i = 0; i < nCalls; i++) {
            vm.prank(actor);
            c.Put{value: amount}(0);
        }

        // General rule: each successful Put appends exactly one History entry,
        // so the Log length equals the number of successful Put calls.
        (,,,, uint256 len) = c.LogFile();
        assertTrue(len == nCalls);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(uint256 amount, address actor, uint256 warpTo) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 10 ether);
        warpTo = bound(warpTo, block.timestamp, block.timestamp + 1000 days);
        vm.warp(warpTo);
        vm.deal(actor, amount);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("Put(uint256)", warpTo));
        assertTrue(ok, "Put reverted");

        // Rule: after a successful Put(amount) the log must contain a new entry
        // attributable to `actor`; the mutant adds none, so index 0 does not exist.
        (bool hasEntry, ) = address(log).call(abi.encodeWithSignature("History(uint256)", 0));
        assertTrue(hasEntry && c.Acc(actor).balance == amount && ok);
    }
}

