pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new C(address(lg));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 10 ether);

        uint256 lenBefore = lg.History_length();

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("Put(uint256)", 0));
        assertTrue(ok, "Put reverted");

        // The newest history entry must be attributable to THIS Put:
        // same sender, same value, and logged at the current timestamp.
        (address sender, string memory data, uint256 val, uint256 time) = lg.History(lenBefore);
        assertTrue(
            lenBefore + 1 == lg.History_length() &&
            sender == actor &&
            val == amount &&
            time == block.timestamp &&
            keccak256(bytes(data)) == keccak256(bytes("Put"))
        );
    }
}

