pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;

    function setUp() public { c = new C(address(new Log())); lg = Log(address(c)); }

    function testFuzz_property(address actor, uint96 amount, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = uint96(bound(uint256(amount), 1, 1 ether));
        vm.deal(actor, uint256(amount));
        uint256 before = block.timestamp;
        vm.prank(actor);
        c.Put{value: uint256(amount)}(unlockTime);
        // c must log the Put: History(0) exists and matches (actor, amount)
        bool ok = true;
        address s; uint256 v;
        try lg.History(0) returns (address s0, string memory, uint256 v0, uint256) {
            s = s0; v = v0;
        } catch {
            ok = false;
        }
        assertTrue(ok && s == actor && v == uint256(amount) && c.Acc(actor).balance == uint256(amount) && c.Acc(actor).unlockTime > before);
    }
}

