pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 deposit, uint256 poke) public {
        deposit = bound(deposit, 2 ether, 100 ether);
        poke = bound(poke, 1, deposit - 1);

        Reentrant attacker = new Reentrant(c, poke);
        vm.deal(address(attacker), deposit + poke);

        // initial Put (unlockTime = now, ok to collect after time passes)
        vm.prank(address(attacker));
        c.Put{value: deposit}(0);
        vm.warp(block.timestamp + 1 days);

        uint256 before = c.Acc(address(attacker)).balance;

        // Collect triggers attacker's receive -> re-entrant Put{value: poke}(0)
        vm.prank(address(attacker));
        c.Collect(deposit);

        // Reference: re-entrant Put reverts (lock held) -> low-level call fails ->
        // balance unchanged. Mutant: re-entrant Put succeeds -> balance changes.
        assertTrue(c.Acc(address(attacker)).balance == before);
    }
}

contract Reentrant {
    C immutable c;
    uint256 immutable poke;

    constructor(C _c, uint256 _poke) {
        c = _c;
        poke = _poke;
    }

    receive() external payable {
        c.Put{value: poke}(0);
    }
}

