pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 deposit, uint256 collectAmt) public {
        vm.assume(deposit >= 1 ether);
        collectAmt = bound(collectAmt, 1, deposit);

        Attacker attacker = new Attacker(c, 1);
        vm.deal(address(attacker), deposit + 1);

        // normal deposit while lock is free
        attacker.deposit{value: deposit}(0);
        vm.warp(block.timestamp + 1);

        attacker.collect(collectAmt);

        (, uint256 bal) = c.Acc(address(attacker));
        // General rule: Collect removes exactly collectAmt from the recorded balance;
        // any deposit made while the lock is held must have reverted.
        assertTrue(bal == deposit - collectAmt);
    }
}

contract Attacker {
    C c;
    uint256 reval;

    constructor(C _c, uint256 _reval) { c = _c; reval = _reval; }

    function deposit(uint256 t) external payable { c.Put{value: msg.value}(t); }

    function collect(uint256 am) external { c.Collect(am); }

    // Re-enter Put while the lock is held during Collect's external call.
    receive() external payable {
        c.Put{value: reval}(0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function runPut(uint v) public {
        require(v > 0);
        require(address(this).balance >= v);
        c.Put{value: v}(0);
        (, uint bal) = c.Acc(address(this));
        assert(bal >= v);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}
    function test(uint amount, uint t) public {
        require(amount > 1 ether);
        require(address(this).balance >= amount);
        c.Put{value: amount}(t);
        c.Collect(amount);
        assert(c.Acc(address(this)).balance < amount);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function test(address logAddr, uint amt, uint t) public payable {
        require(amt >= 1 ether);
        require(address(this).balance >= amt);
        Log log = Log(logAddr);

        // fund the account; unlockTime becomes max(t, now)
        c.Put{value: amt}(t);

        (uint ut, uint bal) = c.Acc(address(this));
        require(bal == amt);
        require(block.timestamp > ut);

        // one successful collect (send to this contract, which accepts ether)
        c.Collect(amt / 2);

        // P logged the collect: entry index 1 exists with Val == amt/2.
        // M skipped AddMessage in Collect, so only index 0 exists and this read reverts.
        (, , uint v, ) = log.History(1);
        assert(v == amt / 2);
    }
}
